#[test]
fn the_fixture_upgrade_ranking_matches_upstream() {
    let (mastery, oracle) = imported();
    let ranking = mastery.ranking();
    let rows = oracle["upgrades"].as_array().expect("upgrades is an array");
    assert_eq!(ranking.len(), rows.len());
    for (position, row) in rows.iter().enumerate() {
        let port = &ranking[position];
        let index = row["t"].as_u64().expect("t is a number") as usize;
        let what = &row["name"].as_str().unwrap_or_default().to_string();
        assert_eq!(port.index, index, "row {position} is {what}");
        assert_eq!(port.name, UPGRADE_NAMES[index]);
        close(port.level, number(row, "curLv"), &format!("{what} level"));
        close(
            port.required_level.into(),
            number(row, "reqLv"),
            &format!("{what} requirement"),
        );
        assert_eq!(
            port.locked,
            row["locked"].as_bool().expect("locked is a bool")
        );
        close(
            port.per_lv,
            number(row, "perLv"),
            &format!("{what} per level"),
        );
        close(
            port.scaling,
            number(row, "scalingFactor"),
            &format!("{what} scaling"),
        );
        close(
            port.bonus,
            number(row, "curBonus"),
            &format!("{what} bonus"),
        );
        close(
            port.next_bonus,
            number(row, "newBonus"),
            &format!("{what} next bonus"),
        );
        close(port.gain, number(row, "gain"), &format!("{what} gain"));
        close(
            port.gain_pct,
            number(row, "pctGain"),
            &format!("{what} gain percentage"),
        );
        close(
            port.rate_after,
            number(row, "newRate"),
            &format!("{what} rate after"),
        );
    }
    // The ranking is a permutation of the EXP upgrades, in gain order.
    let mut indexes: Vec<usize> = ranking.iter().map(|row| row.index).collect();
    indexes.sort_unstable();
    assert_eq!(indexes, EXP_UPGRADES.to_vec());
    assert!(
        ranking
            .windows(2)
            .all(|pair| pair[0].gain_pct >= pair[1].gain_pct),
        "the ranking is ordered by gain"
    );
    // The best point on this save is the one the oracle ranks first.
    let best = rows[0]["name"].as_str().unwrap_or_default();
    assert_eq!(ranking[0].name, best, "the top row is the oracle's top row");
}

#[test]
fn the_fixture_breakdown_root_is_the_rate_and_its_terms_add_up() {
    let (mastery, _) = imported();
    let tree = mastery.breakdown();
    assert_eq!(tree.label, "EXP Rate");
    close(tree.value, mastery.exp_rate(), "the tree root");
    let product: f64 = tree.children.iter().map(|child| child.value).product();
    close(product, tree.value, "the factors multiply to the root");
    // Every EXP upgrade is a factor in the tree, and SMOKY is not.
    for index in EXP_UPGRADES {
        assert!(
            tree.children
                .iter()
                .any(|child| child.label == UPGRADE_NAMES[index]),
            "{} is a factor",
            UPGRADE_NAMES[index]
        );
    }
    assert!(!tree.copy_text().contains(UPGRADE_NAMES[3]));
    // The additive group's children still sum to the percentage it reports.
    let building = tree
        .children
        .iter()
        .find(|child| child.label == "External Multipliers")
        .expect("the external group is in the tree");
    let additive = building
        .children
        .iter()
        .find(|child| child.label == "Additive EXP Bonuses")
        .expect("the additive group is in the tree");
    close(
        additive.sum_children(),
        mastery.external.additive(),
        "additive sum",
    );
}

#[test]
fn an_unlocked_rank_changes_the_ranking_but_not_the_save() {
    let (mastery, _) = imported();
    assert_eq!(mastery.level, 18.0);
    // SOUR and SAVORY are locked at rank 18: their gain is zero and the page
    // lists them anyway, with the requirement it needs.
    for index in [4, 5] {
        let row = mastery
            .ranking()
            .into_iter()
            .find(|row| row.index == index)
            .expect("every EXP upgrade is ranked");
        assert!(row.locked, "{} needs rank {}", row.name, row.required_level);
        assert_eq!(row.required_level, REQUIRED_LEVEL[index]);
        assert_eq!(row.gain, 0.0);
    }
}

#[test]
fn the_fixture_distribution_matches_upstream() {
    let (mastery, oracle) = imported();
    let distribution = &oracle["distribution"];
    let total = number(distribution, "totalPts");
    close(total, mastery.points_earned(), "the page's total points");
    for variant in distribution["variants"]
        .as_array()
        .expect("variants is an array")
    {
        let request = number(variant, "request");
        let what = &format!("budget {request}");
        let plan = mastery.distribution(Goal::Now, request);
        close(plan.budget, number(variant, "spendPts"), what);
        let levels = variant["levels"].as_array().expect("levels is an array");
        for (position, index) in EXP_UPGRADES.iter().enumerate() {
            close(
                plan.levels[*index],
                levels[position].as_f64().unwrap_or_default(),
                &format!("{what}: {}", UPGRADE_NAMES[*index]),
            );
        }
        close(plan.rate, number(variant, "rate"), what);
        close(
            plan.hours,
            number(variant, "hoursToNextLevel"),
            &format!("{what}: hours to the next level"),
        );
    }
    // The plan's rows are the page's table: current, optimal, change and bonus.
    let rows = distribution["rows"].as_array().expect("rows is an array");
    let ports = mastery
        .distribution(Goal::Now, mastery.points_earned())
        .rows;
    assert_eq!(ports.len(), rows.len());
    for row in rows {
        let index = row["t"].as_u64().expect("t is a number") as usize;
        let port = ports
            .iter()
            .find(|port| port.index == index)
            .expect("every EXP upgrade is a row");
        let what = UPGRADE_NAMES[index];
        close(
            port.current,
            number(row, "curLv"),
            &format!("{what} current"),
        );
        close(
            port.planned,
            number(row, "optLv"),
            &format!("{what} planned"),
        );
        close(port.change, number(row, "diff"), &format!("{what} change"));
        close(
            port.bonus,
            number(row, "optBonus"),
            &format!("{what} bonus"),
        );
    }
}

#[test]
fn the_allocator_invariant_holds_on_the_fixture() {
    let (mastery, oracle) = imported();
    let total = number(&oracle["distribution"], "totalPts");
    // Every budget the section can ask for spends exactly the clamped budget and
    // never touches a locked upgrade.
    for request in [0.0, 1.0, total / 2.0, total, total + 7.0] {
        let plan = mastery.distribution(Goal::Now, request);
        let spent: f64 = plan.levels.iter().sum();
        close(spent, plan.budget, "the plan spends its budget");
        assert!(plan.budget <= total, "the plan respects the budget");
        for row in &plan.rows {
            assert!(row.planned >= 0.0, "{} has no negative levels", row.name);
            if row.locked {
                assert_eq!(row.planned, 0.0, "{} stays locked", row.name);
            }
        }
        // The plan's rate is its own factors multiplied, so the table explains
        // the number the card shows.
        let factors: f64 = plan.rows.iter().map(|row| row.multiplier).product();
        close(
            plan.rate,
            2.0 * mastery.external.total() * factors,
            "the plan rate",
        );
        // The plan is deterministic: the same save plans the same way.
        assert_eq!(mastery.distribution(Goal::Now, request), plan);
    }
    // The goal switch re-plans on this save: rank 18 leaves SOUR (25) and
    // SAVORY (100) locked, so holding the budget until 25 buys SOUR.
    let now = mastery.distribution(Goal::Now, total);
    let later = mastery.distribution(Goal::NextUnlock, total);
    assert_eq!(later.rank, 25.0);
    assert_ne!(now.levels, later.levels, "the goal switch changes the plan");
    assert_eq!(
        later.levels[4].min(1.0),
        1.0,
        "SOUR takes points at rank 25"
    );
}

/// The imported fixture's meal state and the oracle's yellow block.
fn imported_yellow() -> (idleon_cooking_mastery::Yellow, Value) {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/data.json");
    let save = std::fs::read_to_string(path).expect("fixtures/data.json is committed");
    let imported = import(&save).expect("the fixture imports");
    (
        imported.yellow.expect("the fixture carries CookMaster"),
        fixture(),
    )
}

/// The upstream unit id of a goal's value.
fn unit_id(unit: idleon_cooking_mastery::Unit) -> &'static str {
    use idleon_cooking_mastery::Unit;
    match unit {
        Unit::Percent => "percent",
        Unit::Flat => "flat",
        Unit::Levels => "levels",
        Unit::Multiplier => "multiplier",
    }
}

#[test]
fn the_fixture_yellow_budget_and_context_match_upstream() {
    let (yellow, oracle) = imported_yellow();
    let upstream = &oracle["yellow"];
    close(
        yellow.budget,
        number(upstream, "budget"),
        "yellow point budget",
    );
    close(
        yellow.cook_multi,
        number(upstream, "cookMulti"),
        "meal multiplier",
    );
    close(
        idleon_cooking_mastery::bonus_multi_cook(20.0),
        number(upstream, "mealMulti"),
        "the mastery factor at 20 points",
    );
    let ribbons = upstream["ribbons"].as_array().expect("ribbons is an array");
    assert_eq!(yellow.ribbons.len(), ribbons.len(), "one ribbon per meal");
    for (meal, expected) in ribbons.iter().enumerate() {
        close(
            yellow.ribbons[meal],
            expected.as_f64().unwrap_or_default(),
            &format!("meal {meal} ribbon"),
        );
    }

    let characters = upstream["characters"]
        .as_array()
        .expect("characters is an array");
    assert_eq!(yellow.characters.len(), characters.len());
    for (index, character) in characters.iter().enumerate() {
        let port = &yellow.characters[index];
        assert_eq!(
            port.name,
            character["name"].as_str().unwrap_or_default(),
            "character {index} name"
        );
        close(
            port.farming,
            number(character, "farmingLv"),
            &format!("character {index} farming"),
        );
        close(
            port.summoning,
            number(character, "summoningLv"),
            &format!("character {index} summoning"),
        );
    }

    let kitchens = &upstream["kitchens"];
    let port = yellow.kitchens();
    assert_eq!(
        port.count as f64,
        number(kitchens, "count"),
        "unlocked kitchens"
    );
    close(
        port.average_levels,
        number(kitchens, "averageLevels"),
        "average upgrade levels",
    );
    close(port.min_steps, number(kitchens, "minSteps"), "min steps");
    close(port.max_steps, number(kitchens, "maxSteps"), "max steps");
    close(
        port.meal_steps,
        number(kitchens, "mealSteps"),
        "meal kitchen steps",
    );
    close(
        port.recipe_steps,
        number(kitchens, "recipeSteps"),
        "recipe kitchen steps",
    );
}

#[test]
fn the_fixture_yellow_budget_counts_the_companion_and_the_event_shop() {
    let (yellow, oracle) = imported_yellow();
    // The fixture save already owns the event shop perk (`OptLacc[311]` holds
    // its letter); the oracle's variant also owns the Rift Spooker, through the
    // Pet Bonus Tokens at `OptLacc[606]`, which is worth five more points.
    let variant = &oracle["yellow"]["budgetVariant"];
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/data.json");
    let mut save: Value = serde_json::from_str(
        &std::fs::read_to_string(path).expect("fixtures/data.json is committed"),
    )
    .expect("the fixture is JSON");
    let event = variant["eventShop"]
        .as_str()
        .expect("eventShop is a string");
    let companion = variant["companionToken"]
        .as_str()
        .expect("companionToken is a string");
    let olalacc = save["OptLacc"].as_array_mut().expect("OptLacc is an array");
    let tokens = olalacc[606]
        .as_str()
        .expect("the token list is a string")
        .to_string();
    olalacc[311] = Value::String(event.to_string());
    olalacc[606] = Value::String(format!("{tokens},{companion}"));
    let imported = import(&serde_json::to_string(&save).expect("the variant serialises"))
        .expect("the variant imports");
    let boosted = imported
        .yellow
        .expect("the variant carries CookMaster")
        .budget;
    close(
        boosted,
        number(variant, "budget"),
        "the budget with the companion and the perk",
    );
    close(
        boosted - yellow.budget,
        5.0,
        "the Rift Spooker's five points",
    );
}

#[test]
fn the_fixture_yellow_goal_table_matches_upstream() {
    let (yellow, oracle) = imported_yellow();
    let goals = oracle["yellow"]["goals"]
        .as_array()
        .expect("goals is an array");
    let offered = yellow.goals();
    assert_eq!(offered.len(), goals.len(), "the offered goals");
    for (position, goal) in goals.iter().enumerate() {
        let port = offered[position];
        let id = goal["id"].as_str().unwrap_or_default();
        assert_eq!(port.id, id, "goal {position}");
        assert_eq!(port.name, goal["name"].as_str().unwrap_or_default(), "{id}");
        let categories: Vec<&str> = goal["categories"]
            .as_array()
            .expect("categories is an array")
            .iter()
            .filter_map(Value::as_str)
            .collect();
        assert_eq!(port.categories, categories, "{id} categories");
        assert_eq!(
            unit_id(port.unit),
            goal["unit"].as_str().unwrap_or_default(),
            "{id} unit"
        );
        assert_eq!(port.note, goal["note"].as_str().unwrap_or_default(), "{id}");
    }
    // A goal with one leveled meal is not offered, and the page's own order is
    // the order here.
    assert!(yellow.goals().iter().all(|goal| goal.id != "crit"));
    assert_eq!(offered[0].id, "seff");
}

/// Compare one upstream plan with the port's allocation.
fn compare_plan(
    yellow: &idleon_cooking_mastery::Yellow,
    plan: &Value,
    character: usize,
    what: &str,
) {
    let goal = plan["goal"].as_str().expect("goal is a string");
    let request = number(plan, "request");
    let port = yellow
        .allocation(goal, request, character)
        .unwrap_or_else(|| panic!("{what}: {goal} has a plan"));
    close(port.requested, request, &format!("{what}: requested"));
    close(port.spent, number(plan, "spend"), &format!("{what}: spent"));
    close(
        port.value,
        number(plan, "goalValue"),
        &format!("{what}: value"),
    );
    close(
        port.current_value,
        number(plan, "curGoalValue"),
        &format!("{what}: current value"),
    );
    let meals = plan["meals"].as_array().expect("meals is an array");
    assert_eq!(port.rows.len(), meals.len(), "{what}: row count");
    for (position, meal) in meals.iter().enumerate() {
        let row = &port.rows[position];
        let name = meal["name"].as_str().unwrap_or_default();
        assert_eq!(
            row.index as f64,
            number(meal, "idx"),
            "{what}: row {position} index"
        );
        assert_eq!(row.name, name, "{what}: row {position} name");
        assert_eq!(
            row.category,
            meal["cat"].as_str().unwrap_or_default(),
            "{what}: {name} category"
        );
        close(
            row.level,
            number(meal, "mealLv"),
            &format!("{what}: {name} level"),
        );
        close(
            row.bonus,
            number(meal, "base"),
            &format!("{what}: {name} base"),
        );
        close(
            row.base_weight,
            number(meal, "baseWeight"),
            &format!("{what}: {name} base weight"),
        );
        close(
            row.current,
            number(meal, "curLv"),
            &format!("{what}: {name} current"),
        );
        close(
            row.allocated,
            number(meal, "optLv"),
            &format!("{what}: {name} allocated"),
        );
    }
}

#[test]
fn the_fixture_yellow_allocation_matches_upstream() {
    let (yellow, oracle) = imported_yellow();
    for goal in oracle["yellow"]["goals"]
        .as_array()
        .expect("goals is an array")
    {
        let id = goal["id"].as_str().unwrap_or_default();
        for plan in goal["plans"].as_array().expect("plans is an array") {
            let request = number(plan, "request");
            compare_plan(&yellow, plan, 0, &format!("{id} at {request}"));
        }
        for plan in goal["characterPlans"]
            .as_array()
            .expect("characterPlans is an array")
        {
            let character = number(plan, "charIdx") as usize;
            compare_plan(
                &yellow,
                plan,
                character,
                &format!("{id} on character {character}"),
            );
        }
    }
}

#[test]
fn the_yellow_allocator_invariant_holds_on_the_fixture() {
    let (yellow, oracle) = imported_yellow();
    let budget = yellow.budget;
    for goal in yellow.goals() {
        let full = yellow
            .allocation(goal.id, budget, 0)
            .expect("an offered goal has a plan");
        // The plan spends its budget and never more, whatever it was asked for.
        close(
            full.spent,
            budget,
            &format!("{} spends the budget", goal.id),
        );
        assert_eq!(
            full.rows.iter().map(|row| row.allocated).sum::<f64>(),
            full.spent,
            "{}: the rows add up to the spend",
            goal.id
        );
        assert!(full.rows.iter().all(|row| row.allocated >= 0.0));
        assert!(
            full.rows
                .iter()
                .all(|row| goal.categories.contains(&row.category.as_str())),
            "{} only spends on its own categories",
            goal.id
        );
        // The rows are ordered by the points they take.
        assert!(
            full.rows
                .windows(2)
                .all(|pair| pair[0].allocated >= pair[1].allocated),
            "{}: the table is ordered by the allocation",
            goal.id
        );
        // The plan is deterministic and never spends on a negative request.
        assert_eq!(yellow.allocation(goal.id, budget, 0), Some(full.clone()));
        let negative = yellow
            .allocation(goal.id, -5.0, 0)
            .expect("an offered goal has a plan");
        assert_eq!(negative.spent, 0.0);
        assert_eq!(negative.value, negative.current_value);
        assert!(
            negative.rejected(),
            "{}: a negative budget is rejected",
            goal.id
        );
        let over = yellow
            .allocation(goal.id, budget + 10.0, 0)
            .expect("an offered goal has a plan");
        assert_eq!(over.spent, budget, "{}: the budget caps the spend", goal.id);
        assert!(
            over.rejected(),
            "{}: an over-budget request is rejected",
            goal.id
        );
    }
    // Switching the goal re-plans on this save: the points land on other meals.
    let first = yellow.allocation("seff", budget, 0).expect("seff");
    let second = yellow.allocation("totdmg", budget, 0).expect("totdmg");
    assert_ne!(first.rows, second.rows, "the goal switch changes the plan");
    assert_ne!(first.value, second.value);
    // The character context moves the stat goals that scale with a character.
    let anna = yellow.allocation("mcook", budget, 0).expect("mcook");
    let other = yellow.allocation("mcook", budget, 1).expect("mcook");
    assert!(anna.value > 0.0 && other.value > 0.0);
    assert_eq!(anna.character_name(&yellow), "Character 1");
    assert!(
        !oracle["yellow"]["characters"]
            .as_array()
            .expect("characters")
            .is_empty()
    );
}
